def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        g, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return (g, x, y)

def chinese_remainder_theorem(remainders, moduli):
    total_sum = 0
    prod = 1
    for modulus in moduli:
        prod *= modulus

    for rem, mod in zip(remainders, moduli):
        p = prod // mod
        _, coeff, _ = extended_gcd(p, mod)
        total_sum += rem * coeff * p
    return total_sum % prod,

def solve(inputs: dict) -> float:
    remainders = inputs['REMAINDERS']
    moduli = inputs['MODULI']
    result = chinese_remainder_theorem(remainders, moduli)
    return result[0]

